"""The ``stockroom`` command line."""

from __future__ import annotations

import csv
import datetime
import io
import json
import os
import sys
from typing import Dict, List, Optional, Sequence, Tuple

from .model import Movement, Order, ParseError, Product, Quote
from .parse import (
    check_balances,
    iter_lines,
    normalise_order_id,
    normalise_sku,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
    parse_uint,
    stock_levels,
)
from .pricing import price_order

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND [ARGS]\n"
    "commands: stock [--json] | low [--json] | history SKU [--json] |\n"
    "          receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE] |\n"
    "          quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json] |\n"
    "          report [--format text|csv|json]"
)

_WS = " \t"


class _Stop(Exception):
    """End the command with an exit status and a message on stderr."""

    def __init__(self, code: int, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def _usage(message: str) -> _Stop:
    return _Stop(2, "%s\n%s" % (message, USAGE))


# --------------------------------------------------------------- file access


class _Files:
    def __init__(self, directory: str) -> None:
        self.directory = directory

    def _read(self, name: str, required: bool) -> Tuple[bytes, str]:
        path = os.path.join(self.directory, name)
        try:
            with open(path, "rb") as handle:
                raw = handle.read()
        except FileNotFoundError:
            if required:
                raise _Stop(2, "%s: cannot read file: no such file" % path)
            return b"", ""
        except OSError as exc:
            raise _Stop(2, "%s: cannot read file: %s" % (path, exc.strerror or exc))
        try:
            return raw, raw.decode("utf-8")
        except UnicodeDecodeError:
            raise _Stop(2, "%s: not valid UTF-8" % path)

    def catalog(self) -> Dict[str, Product]:
        return self._parsed("catalog.txt", self._read("catalog.txt", True)[1], parse_catalog)

    def movements_raw(self, catalog: Dict[str, Product]) -> Tuple[bytes, str, List[Movement]]:
        raw, text = self._read("movements.txt", False)
        return raw, text, self._parsed("movements.txt", text, lambda t: parse_movements(t, catalog))

    def movements(self, catalog: Dict[str, Product]) -> List[Movement]:
        return self.movements_raw(catalog)[2]

    def orders(self, catalog: Dict[str, Product]) -> List[Order]:
        text = self._read("orders.txt", False)[1]
        return self._parsed("orders.txt", text, lambda t: parse_orders(t, catalog))

    @staticmethod
    def _parsed(name, text, parser):
        try:
            return parser(text)
        except ParseError as exc:
            raise _Stop(1, "%s: %s" % (name, exc))

    def append_movements(self, existing: bytes, lines: Sequence[str]) -> None:
        data = "".join(line + "\n" for line in lines).encode("utf-8")
        if existing and not existing.endswith(b"\n"):
            data = b"\n" + data
        path = os.path.join(self.directory, "movements.txt")
        try:
            with open(path, "ab") as handle:
                handle.write(data)
        except OSError as exc:
            raise _Stop(2, "%s: cannot write file: %s" % (path, exc.strerror or exc))


# ------------------------------------------------------------------- helpers


def _dump(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def _lines(rows: Sequence[str]) -> str:
    return "".join(row + "\n" for row in rows)


def _counting_order(movements: Sequence[Movement]) -> List[Movement]:
    return sorted(movements, key=lambda m: m.date)


def _status(owed_total: int, shipped_total: int) -> str:
    if owed_total == 0:
        return "complete"
    return "open" if shipped_total == 0 else "partial"


def _shipped_so_far(order: Order, movements: Sequence[Movement]) -> List[int]:
    note = "order %s" % order.id
    shipped = []
    for sku, quantity in order.lines:
        total = sum(-m.quantity for m in movements if m.sku == sku and m.quantity < 0 and m.note == note)
        shipped.append(min(total, quantity))
    return shipped


def _find_order(orders: Sequence[Order], arg: str) -> Order:
    wanted = normalise_order_id(arg)
    for order in orders:
        if order.id == wanted:
            return order
    raise _Stop(1, "unknown order %s" % arg)


def _require_sku(catalog: Dict[str, Product], arg: str) -> str:
    sku = normalise_sku(arg)
    if sku is None or sku not in catalog:
        raise _Stop(1, "unknown SKU %s" % arg)
    return sku


def _quote_text(header: str, order: Order, quote: Quote) -> str:
    rows = ["%s%s %s %s" % (header, order.id, order.date.isoformat(), order.customer)]
    for ln in quote.lines:
        rows.append("%s %d %s %s %s %s" % (ln.sku, ln.quantity, ln.unit, ln.gross, ln.discount, ln.net))
    rows.append("subtotal %s" % quote.subtotal)
    rows.append("order discount %s" % quote.order_discount)
    rows.append("tax %s" % quote.tax)
    rows.append("total %s" % quote.total)
    return _lines(rows)


def _quote_json(order: Order, quote: Quote) -> str:
    return _dump(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": ln.sku,
                    "quantity": ln.quantity,
                    "unit": str(ln.unit),
                    "gross": str(ln.gross),
                    "discount": str(ln.discount),
                    "net": str(ln.net),
                }
                for ln in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        }
    )


def _invoice_order(order: Order, shipped: Sequence[int]) -> Order:
    lines = [(sku, n) for (sku, _), n in zip(order.lines, shipped) if n > 0]
    return Order(order.id, order.date, order.customer, lines)


# ------------------------------------------------------------------ commands


def _stock(files: _Files, args: List[str], as_json: bool) -> str:
    catalog = files.catalog()
    levels = stock_levels(catalog, files.movements(catalog))
    rows = []
    for sku in sorted(catalog):
        product, onhand = catalog[sku], levels[sku]
        if onhand == 0:
            status = "out"
        elif onhand <= product.reorder:
            status = "low"
        else:
            status = "ok"
        rows.append((sku, product.name, onhand, status))
    if as_json:
        return _dump([{"sku": s, "name": n, "onhand": o, "status": st} for s, n, o, st in rows])
    return _lines(["%s %d %s %s" % (s, o, st, n) for s, n, o, st in rows])


def _low(files: _Files, args: List[str], as_json: bool) -> str:
    catalog = files.catalog()
    levels = stock_levels(catalog, files.movements(catalog))
    rows = []
    for sku in sorted(catalog):
        onhand, reorder = levels[sku], catalog[sku].reorder
        if onhand <= reorder:
            rows.append((sku, onhand, reorder, max(1, 2 * reorder - onhand)))
    if as_json:
        return _dump([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return _lines(["%s %d %d %d" % row for row in rows])


def _history(files: _Files, args: List[str], as_json: bool) -> str:
    catalog = files.catalog()
    movements = files.movements(catalog)
    sku = _require_sku(catalog, args[0])
    rows = []
    balance = 0
    for move in _counting_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        rows.append((move.date.isoformat(), "%+d" % move.quantity, balance, move.note))
    if as_json:
        return _dump([{"date": d, "delta": dl, "balance": b, "note": n} for d, dl, b, n in rows])
    return _lines(["%s %s %d%s" % (d, dl, b, " " + n if n else "") for d, dl, b, n in rows])


def _append_one(files: _Files, args: List[str], sign: int) -> str:
    date = parse_date(args[0])
    catalog = files.catalog()
    raw, text, _ = files.movements_raw(catalog)
    sku = _require_sku(catalog, args[1])
    quantity = parse_uint(args[2])
    if quantity is None or quantity < 1:
        raise _Stop(1, "quantity must be a whole number of one or more, not %r" % args[2])
    note = args[3].strip(_WS) if len(args) == 4 else ""
    if "\r" in note or "\n" in note:
        raise _Stop(1, "note must not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise _Stop(1, "note is not valid UTF-8 text")
    line = "%s %s %+d%s" % (date.isoformat(), sku, sign * quantity, " " + note if note else "")
    _check_append(text, raw, line, catalog)
    files.append_movements(raw, [line])
    return line + "\n"


def _check_append(text: str, raw: bytes, new_text: str, catalog: Dict[str, Product]) -> None:
    combined = text + ("\n" if raw and not raw.endswith(b"\n") else "") + new_text + "\n"
    try:
        parse_movements(combined, catalog)
    except ParseError as exc:
        raise _Stop(1, "movements.txt: %s" % exc)


def _receive(files: _Files, args: List[str], as_json: bool) -> str:
    return _append_one(files, args, 1)


def _ship(files: _Files, args: List[str], as_json: bool) -> str:
    return _append_one(files, args, -1)


def _quote(files: _Files, args: List[str], as_json: bool) -> str:
    catalog = files.catalog()
    order = _find_order(files.orders(catalog), args[0])
    quote = price_order(order, catalog)
    return _quote_json(order, quote) if as_json else _quote_text("", order, quote)


def _fulfil(files: _Files, args: List[str], as_json: bool) -> str:
    date = parse_date(args[1])
    catalog = files.catalog()
    raw, text, movements = files.movements_raw(catalog)
    order = _find_order(files.orders(catalog), args[0])
    if date < order.date:
        raise _Stop(1, "cannot fulfil %s on %s: before the order date %s" % (order.id, date, order.date))
    done = _shipped_so_far(order, movements)
    ordered = _counting_order(movements)
    rows, new_lines = [], []
    owed_total = shipped_total = 0
    for (sku, quantity), before in zip(order.lines, done):
        owed = quantity - before
        balance, upto, later = 0, 0, None
        for move in ordered:
            if move.sku != sku:
                continue
            balance += move.quantity
            if move.date <= date:
                upto = balance
            else:
                later = balance if later is None else min(later, balance)
        ship = max(0, min(owed, upto, upto if later is None else later))
        if ship:
            new_lines.append("%s %s -%d order %s" % (date.isoformat(), sku, ship, order.id))
        rows.append("%s shipped %d backordered %d" % (sku, ship, owed - ship))
        owed_total += owed - ship
        shipped_total += before + ship
    if new_lines:
        _check_append(text, raw, "\n".join(new_lines), catalog)
        files.append_movements(raw, new_lines)
    rows.append("status %s" % _status(owed_total, shipped_total))
    return _lines(rows)


def _invoice(files: _Files, args: List[str], as_json: bool) -> str:
    catalog = files.catalog()
    movements = files.movements(catalog)
    order = _find_order(files.orders(catalog), args[0])
    shipped = _shipped_so_far(order, movements)
    if not any(shipped):
        raise _Stop(1, "nothing shipped yet for %s" % order.id)
    billed = _invoice_order(order, shipped)
    quote = price_order(billed, catalog)
    return _quote_json(billed, quote) if as_json else _quote_text("invoice ", billed, quote)


def _report(files: _Files, args: List[str], fmt: str) -> str:
    catalog = files.catalog()
    movements = files.movements(catalog)
    orders = files.orders(catalog)
    orders = sorted(orders, key=lambda o: (o.date, int(o.id[3:]), o.id))
    rows = []
    for order in orders:
        shipped = _shipped_so_far(order, movements)
        ordered_units = sum(q for _, q in order.lines)
        shipped_units = sum(shipped)
        status = _status(ordered_units - shipped_units, shipped_units)
        quoted = price_order(order, catalog).total
        invoiced = price_order(_invoice_order(order, shipped), catalog).total if shipped_units else None
        rows.append(
            (order.id, order.date.isoformat(), order.customer, status, ordered_units, shipped_units,
             str(quoted), str(invoiced) if invoiced is not None else "0.00")
        )
    if fmt == "json":
        keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
        return _dump([dict(zip(keys, row)) for row in rows])
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"])
        writer.writerows(rows)
        return buffer.getvalue()
    return _lines(
        ["%s %s %s %s %d/%d %s %s" % (o, d, c, st, sh, od, q, i) for o, d, c, st, od, sh, q, i in rows]
    )


# command: (min positional, max positional, option kind)
#   option kind: "json" (accepts --json), "format" (accepts --format), "raw" (no options but --dir)
_COMMANDS = {
    "stock": (0, 0, "json"),
    "low": (0, 0, "json"),
    "history": (1, 1, "json"),
    "receive": (3, 4, "raw"),
    "ship": (3, 4, "raw"),
    "quote": (1, 1, "json"),
    "fulfil": (2, 2, "raw"),
    "invoice": (1, 1, "json"),
    "report": (0, 0, "format"),
}


def _dispatch(name: str, files: _Files, args: List[str], as_json: bool, fmt: str) -> str:
    if name == "stock":
        return _stock(files, args, as_json)
    if name == "low":
        return _low(files, args, as_json)
    if name == "history":
        return _history(files, args, as_json)
    if name == "receive":
        return _receive(files, args, as_json)
    if name == "ship":
        return _ship(files, args, as_json)
    if name == "quote":
        return _quote(files, args, as_json)
    if name == "fulfil":
        return _fulfil(files, args, as_json)
    if name == "invoice":
        return _invoice(files, args, as_json)
    return _report(files, args, fmt)


def _run(argv: Sequence[str]) -> str:
    directory = "."
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise _usage("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1

    if not rest:
        raise _usage("no command given")
    name, rest = rest[0], rest[1:]
    if name not in _COMMANDS:
        raise _usage("unknown command %r" % name)
    low, high, kind = _COMMANDS[name]

    positional: List[str] = []
    as_json = False
    fmt = "text"
    j = 0
    while j < len(rest):
        arg = rest[j]
        j += 1
        if kind != "raw" and arg.startswith("-") and len(arg) > 1:
            if kind == "json" and arg == "--json":
                as_json = True
            elif kind == "format" and arg == "--format":
                if j >= len(rest):
                    raise _usage("option --format needs a value")
                fmt = rest[j]
                j += 1
            elif kind == "format" and arg.startswith("--format="):
                fmt = arg[len("--format="):]
            else:
                raise _usage("unknown option %r" % arg)
        else:
            positional.append(arg)
    if not low <= len(positional) <= high:
        raise _usage("wrong number of arguments for %s" % name)
    if kind == "format" and fmt not in ("text", "csv", "json"):
        raise _usage("bad --format value %r (text, csv or json)" % fmt)
    if name in ("receive", "ship") and parse_date(positional[0]) is None:
        raise _usage("not a date (YYYY-MM-DD): %r" % positional[0])
    if name == "fulfil" and parse_date(positional[1]) is None:
        raise _usage("not a date (YYYY-MM-DD): %r" % positional[1])

    files = _Files(directory)
    return _dispatch(name, files, positional, as_json, fmt)


def _write(stream, text: str, errors: str = "strict") -> None:
    stream.write(text.encode("utf-8", errors))
    stream.flush()


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        output = _run(args)
    except _Stop as stop:
        try:
            _write(sys.stderr.buffer, "stockroom: %s\n" % stop.message, "backslashreplace")
        except (BrokenPipeError, OSError):
            pass
        return stop.code
    try:
        if output:
            _write(sys.stdout.buffer, output, "replace")
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except OSError:
            pass
    return 0

