class ParseError(ValueError):
    """A mistake in one of the text files; ``line`` counts from 1."""

    def __init__(self, line: int, reason: str) -> None:
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (ParseError, (self.line, self.reason))


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal
